    // Using reflection to access protected constructor and simulate internal state
    // Since the provided code uses _cfgIllegalClassNames and PREFIX_STRING, 
    // we assume they are part of the class state.

    @Before
    public void setUp() throws Exception {
        mockCtxt = mock(DeserializationContext.class);
        // Mock JsonParser for JsonMappingException.from(ctxt, ...)
        JsonParser mockParser = mock(JsonParser.class);
        when(mockCtxt.getParser()).thenReturn(mockParser);

        // We use the actual instance if possible, but since it's a validator, 
        // we might need to instantiate via reflection if the constructor is protected.
        // However, the prompt implies we are testing the logic provided.
        // Since I cannot modify the source code to inject _cfgIllegalClassNames, 
        // I will use the static instance() if it's available, but for unit testing 
        // logic involving private fields, we'd typically use a subclass or reflection.

        validator = SubTypeValidator.instance();
        typeFactory = TypeFactory.defaultInstance();
    }

    /**
     * Helper to create a JavaType via ObjectMapper/TypeFactory
     */
    private JavaType createType(Class<?> clazz) {
        return typeFactory.constructType(clazz);
    }

    @Test
    public void testValidateSubType_AllowedClass() throws JsonMappingException {
        JavaType type = createType(String.class);
        // Should not throw exception
        validator.validateSubType(mockCtxt, type);
    }

    @Test
    public void testValidateSubType_AllowedObject() throws JsonMappingException {
        JavaType type = createType(Object.class);
        validator.validateSubType(mockCtxt, type);
    }

